  const out = []
  const walk = (n, path) => {
    if (n.t === 'table') {
      for (const k of sortedKeys(n.map)) {
        const p = path === null ? k : `${path}.${k}`
        out.push(`${p} ${n.map.get(k).t}`)
        walk(n.map.get(k), p)
