  const root = newTable()
  let current = root
  let currentPath = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const s = lines[i]
    let p = 0
    const fail = (m) => { throw new ParseError(lineNo, m) }
    const skipWs = () => { while (isWs(s[p])) p++ }
    const atEnd = () => p >= s.length || s[p] === '#' || s[p] === ';'

    skipWs()
    if (p >= s.length || s[p] === '#' || s[p] === ';') continue

    function parseBasic() {
      p++
      let out = ''
      for (;;) {
        if (p >= s.length) fail('unterminated string')
        const c = s[p]
        if (c === '"') { p++; return out }
        if (c !== '\\') { out += c; p++; continue }
        p++
        if (p >= s.length) fail('unterminated string')
        const e = s[p]
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (e in map) { out += map[e]; p++ } else if (e === 'u') {
          const h = s.slice(p + 1, p + 5)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          p += 5
        } else {
          const ch = String.fromCodePoint(s.codePointAt(p))
          fail('invalid escape \\' + ch)
        }
      }
    }

    function parseLiteral() {
      const q = s.indexOf("'", p + 1)
      if (q < 0) fail('unterminated string')
      const v = s.slice(p + 1, q)
      p = q + 1
      return v
    }

    function parseName() {
      const c = s[p]
      if (c === '"') return parseBasic()
      if (c === "'") return parseLiteral()
      const st = p
      while (isBare(s[p])) p++
      if (p === st) fail('expected a name')
      return s.slice(st, p)
    }

    function parseDotted() {
      skipWs()
      const names = [parseName()]
      for (;;) {
        const save = p
        skipWs()
        if (s[p] === '.') {
          p++
          skipWs()
          names.push(parseName())
        } else { p = save; return names }
      }
    }

    // Descend through names (all but the last handled by caller) from `table`.
    function walk(table, base, names, notTableMsg) {
      let t = table
      const path = [...base]
      for (const n of names) {
        path.push(n)
        let nx = t.map.get(n)
        if (!nx) {
          nx = newTable()
          t.map.set(n, nx)
        } else if (nx.t === 'array' && nx.aot) {
          nx = nx.items[nx.items.length - 1]
        } else if (nx.t !== 'table') {
          fail(`${path.join('.')} is not a table`)
        }
        t = nx
      }
      return { t, path }
    }

    function assign(table, base, names, value) {
      const { t, path } = walk(table, base, names.slice(0, -1))
      const last = names[names.length - 1]
      if (t.map.has(last)) fail(`key ${[...path, last].join('.')} is defined twice`)
      t.map.set(last, value)
    }

    function parseValue(inArray) {
      skipWs()
      if (atEnd() || s[p] === ',' || s[p] === ']' || s[p] === '}') fail('expected a value')
