        p++
        const arr = { t: 'array', items: [], aot: false }
        for (;;) {
          skipWs()
          if (atEnd()) fail('unterminated array')
          if (s[p] === ']') { p++; return arr }
          arr.items.push(parseValue())
          skipWs()
          if (s[p] === ',') { p++; continue }
          if (s[p] === ']') { p++; return arr }
          fail('unterminated array')
        }
      }
      if (c === '{') {
        p++
        const tab = newTable()
        skipWs()
        if (atEnd()) fail('unterminated inline table')
        if (s[p] === '}') { p++; return tab }
        for (;;) {
          skipWs()
          if (atEnd()) fail('unterminated inline table')
          const names = parseDotted()
          skipWs()
