      if (aot) {
        if (s[p] !== ']') fail('unterminated table header')
        p++
      }
      skipWs()
      if (!atEnd()) fail('trailing text after a table header')

      const { t: parent, path } = walk(root, [], names.slice(0, -1))
      const last = names[names.length - 1]
      const full = [...path, last].join('.')
      const ex = parent.map.get(last)
      if (!aot) {
        if (!ex) {
          const nt = newTable()
          nt.header = true
          parent.map.set(last, nt)
          current = nt
        } else if (ex.t === 'table') {
          if (ex.header) fail(`table ${full} is defined twice`)
          ex.header = true
          current = ex
        } else fail(`${full} is not a table`)
      } else {
        const nt = newTable()
        nt.header = true
        if (!ex) parent.map.set(last, { t: 'array', items: [nt], aot: true })
        else if (ex.t === 'array' && ex.aot) ex.items.push(nt)
        else fail(`${full} is not an array of tables`)
        current = nt
      }
      currentPath = [...path, last]
      continue
    }

    const names = parseDotted()
    skipWs()
    if (s[p] !== '=') fail('expected key = value')
    p++
    pathHolder.base = currentPath
    const v = parseValue()
    skipWs()
    if (!atEnd()) fail('trailing text after a value')
    assign(current, currentPath, names, v)
  }
  return root
}
